<?php require_once __DIR__.'/../includes/auth.php'; require_role(['student']); $pageTitle='My Claims'; require __DIR__.'/../includes/header.php'; $s=$pdo->prepare('SELECT c.*,r.item_name FROM claim_requests c JOIN item_reports r ON r.id=c.item_report_id WHERE c.claimant_id=? ORDER BY c.created_at DESC');$s->execute([current_user()['id']]);$rows=$s->fetchAll();echo '<h1>My claims</h1><div class="table-wrap"><table><tr><th>Item</th><th>Status</th><th>Submitted</th></tr>';foreach($rows as $r){echo '<tr><td>'.e($r['item_name']).'</td><td>'.e($r['status']).'</td><td>'.e($r['created_at']).'</td></tr>';}echo '</table></div>'; require __DIR__.'/../includes/footer.php'; ?>